    if (k1.size() != 2 || k1[0].Kind != 2 || k1[1].Tag != 3) bad |= 2;
    if (g_Blocks != 2) bad |= 4;                                   // only the two SUBM chunks still counted
    MeshChunk empty;
    CopyTo(subs, &empty);                                          // no sub-mesh chunk: nothing happens
    if (g_Blocks != 2) bad |= 8;
